<?php if(!defined('ABSPATH'))exit;if(!is_user_logged_in()){wp_safe_redirect(wp_login_url(home_url('/business-center/')));exit;}get_header();$u=wp_get_current_user();$client=legacyx_find_client_by_wp_user(get_current_user_id());$d=$client?legacyx_business_get_client_data($client->ID):legacyx_business_defaults();?><main class="legacyx-credit-center"><div class="legacyx-credit-shell"><a class="legacyx-credit-back" href="<?php echo esc_url(home_url('/client-portal/'));?>">← Client Command Center</a><header class="legacyx-credit-head"><div><span class="kicker">LEGACY X FIRM OS · BUSINESS</span><h1>Business Center</h1><p>Your coordinated enterprise workspace for entity structure, ownership, compliance, operations, strategy and growth readiness.</p></div><div class="legacyx-credit-identity"><span>Principal</span><strong><?php echo esc_html($u->display_name?:$u->user_login);?></strong><?php if($client):?><small><?php echo esc_html(get_post_meta($client->ID,'_legacyx_client_id',true));?></small><?php endif;?></div></header><?php if(!$client):?><div class="legacyx-portal-notice"><strong>Business profile connection pending.</strong> Your Universal Client Profile must be connected before enterprise information can be displayed.</div><?php else:?><section class="legacyx-credit-summary"><div><span>Entity Type</span><strong><?php echo esc_html($d['entity_type']?:'Not recorded');?></strong></div><div><span>Formation</span><strong><?php echo esc_html($d['formation_status']);?></strong></div><div><span>Compliance</span><strong><?php echo esc_html($d['compliance_status']);?></strong></div><div><span>Operations</span><strong><?php echo esc_html($d['operations_stage']);?></strong></div></section><section class="legacyx-credit-action"><span>Next Recommended Action</span><p><?php echo esc_html($d['next_action']);?></p></section><div class="legacyx-credit-tracks"><section class="legacyx-credit-track"><div class="legacyx-track-title"><span>ENTERPRISE FOUNDATION</span><h2>Business Profile</h2><p>Core information used to coordinate your business advisory relationship.</p></div><div class="legacyx-step-list"><article class="legacyx-credit-step"><span class="legacyx-step-num">01</span><div><h3>Entity & Jurisdiction</h3><p><?php echo esc_html(($d['entity_type']?:'Entity not recorded').' · '.($d['state']?:'Jurisdiction not recorded'));?></p></div><b>→</b></article><article class="legacyx-credit-step"><span class="legacyx-step-num">02</span><div><h3>EIN / Tax Identity</h3><p><?php echo esc_html($d['ein_status']);?></p></div><b>→</b></article><article class="legacyx-credit-step"><span class="legacyx-step-num">03</span><div><h3>Business Banking</h3><p><?php echo esc_html($d['banking_status']);?></p></div><b>→</b></article><article class="legacyx-credit-step"><span class="legacyx-step-num">04</span><div><h3>Strategic Objective</h3><p><?php echo esc_html($d['strategic_goal']?:'Strategic objective not yet recorded.');?></p></div><b>→</b></article></div></section><section class="legacyx-credit-track"><div class="legacyx-track-title"><span>BUSINESS READINESS</span><h2>7-Step Enterprise System</h2><p>A structured path from business foundation through capital and expansion readiness.</p></div><div class="legacyx-step-list"><?php foreach($d['readiness_steps'] as $i=>$step):?><article class="legacyx-credit-step"><span class="legacyx-step-num"><?php echo sprintf('%02d',$i+1);?></span><div><h3><?php echo esc_html($step);?></h3><p>Managed through your Universal Client Profile and Legacy X Firm advisory workflow.</p></div><b>→</b></article><?php endforeach;?></div></section></div><?php endif;?></div></main><?php get_footer();?>